+.badge {
+  display: inline-flex;
+  flex: none;
+  align-items: center;
+  padding: 2px 7px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 3px;
+  color: var(--thorp-copy);
+  font-size: 0.63rem;
+  font-weight: 700;
+  white-space: nowrap;
+}
+
+/* 미검증은 "통과"가 아니라 "말할 수 없음"이다. 경고색을 쓰되 뜻은 글자가 진다. */
+.badge[data-label='UNVALIDATED'] {
+  border-color: var(--thorp-warning);
+  color: var(--thorp-warning);
+}
+
+.badge[data-label='SEARCH_RESULT'] {
+  border-color: var(--thorp-line-strong);
+  color: var(--thorp-muted);
+}
+
+/* 검증 구간 결과라고 해서 좋은 값이라는 뜻은 아니다 — 긍정색을 쓰지 않는다. */
+.badge[data-label='HELD_OUT_RESULT'] {
+  border-color: var(--thorp-accent);
+  color: var(--thorp-accent-soft);
+}
+
+.srOnly {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}

